import workcell, json
from pathlib import Path
p=Path.home()/'spring_measurements.jsonl'
def call(*args):
 r=workcell.call(*args)
 if not r.ok: raise RuntimeError(r.text)
 return r
with p.open('w') as f:
 for i in range(22):
  s=call('arm','status'); force=call('ft','read','1000')
  row={'z_mm':s.data['tip_mm'][2], 'fz_N':force.data['fz']}
  f.write(json.dumps(row)+'\n'); f.flush(); print(row,flush=True)
  if row['fz_N']>=50: break
  if row['z_mm']<95: raise RuntimeError('travel limit')
  r=call('arm','step','-0.5'); print(r.text,flush=True)
